import{_ as l,o as t,c as a,a7 as i}from"./chunks/framework.DUCm5Bu5.js";const p=JSON.parse('{"title":"변경 기록","description":"공개 릴리스의 날짜별 변경 사항입니다.","frontmatter":{"title":"변경 기록","description":"공개 릴리스의 날짜별 변경 사항입니다.","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"ko/project/changelog.md","filePath":"ko/project/changelog.md"}'),o={name:"ko/project/changelog.md"};function r(c,e,n,s,u,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="미출시-—-2026-10-18-utc-08-00" tabindex="-1">미출시 — 2026-10-18 (UTC+08:00) <a class="header-anchor" href="#미출시-—-2026-10-18-utc-08-00" aria-label="Permalink to &quot;미출시 — 2026-10-18 (UTC+08:00)&quot;">​</a></h2><ul><li>4개 언어 가이드를 검증 가능한 절차와 함께 확장했습니다. 설치와 빠른 시작은 소스 빌드와 아직 공개되지 않은 빌드 패키지를 구분하고, 설정은 profile 구성, 환경 변수, 포트, 영속성, 클라이언트 데이터를 다루며, 배포는 Docker Compose, 백업, 업그레이드와 롤백을 설명합니다. 문제 해결은 증상 → 확인 → 원인 → 해결 순서로 구성했습니다.</li><li>플러그인 가이드에 실행 가능한 첫 플러그인 절차를 추가하고 SDK 프로토콜 참고 문서에 언어별 빠른 시작, 기능 협상, 적합성 테스트 내용을 보강했습니다.</li><li>영어와 중국어 README를 다시 작성하여 요구 사항, Windows/Linux 빠른 시작, Docker Compose, 클라이언트 데이터 경계와 문서 진입점을 담았습니다.</li><li>현재 코드와 맞지 않던 설명을 수정했습니다. 아직 공개되지 않은 다운로드와 설치 진입점은 계속 &quot;곧 제공&quot;으로 표시합니다. 이번 변경은 문서에 한정되며 실행 동작은 바뀌지 않았습니다.</li><li>4개 언어로 런처 가이드를 추가했습니다. 동반 Fantasy Tale Launcher의 클라이언트 빌드, 세션과 로그인 티켓 모델, hook 플러그인, 배포 경계, 그리고 운영자를 위한 서버 <code>launcher.http</code> API(HTTP 426 버전 게이트, JSON 호환 규칙, 티켓 보안 경계 포함)를 다룹니다. 문서만 변경되었습니다.</li></ul><h2 id="미출시-—-2026-10-16-utc-08-00" tabindex="-1">미출시 — 2026-10-16 (UTC+08:00) <a class="header-anchor" href="#미출시-—-2026-10-16-utc-08-00" aria-label="Permalink to &quot;미출시 — 2026-10-16 (UTC+08:00)&quot;">​</a></h2><ul><li>네이티브 이벤트 버스에 선언형 SDK 이벤트를 추가하여 언어 간 순차/병렬 알림, waterfall 인터셉트와 bail 결정을 지원합니다.</li><li>이벤트 후속 호출의 소유권과 Rust 콜백 정리를 보완하고 종료 중 이미 기록된 활성화 시간 초과를 놓칠 수 있는 경쟁 조건을 수정했습니다.</li><li>Python, TypeScript, Go, Rust에 SDK 서비스 제공자, 데코레이터 체인과 순서형 서비스 컬렉션을 추가했습니다. Go/Rust WebAssembly도 포함됩니다.</li><li>취소와 시간 초과 후에도 시작된 작업의 소유권을 유지하고 새 정의 게시 후 시작 시 선택 순서를 수정했습니다.</li><li>플러그인 행의 시간 초과 후에도 SDK 정리를 수행하며, 공유 프로세스가 실행 중인 동안에도 제거된 활성화 컨텍스트를 회수할 수 있도록 수정했습니다.</li><li>플러그인 및 SDK 가이드에 등록 예제, 수명 규칙과 아직 구현되지 않은 네이티브 동등성 범위를 명시했습니다.</li></ul><h2 id="미출시-—-2026-10-15-utc-08-00" tabindex="-1">미출시 — 2026-10-15 (UTC+08:00) <a class="header-anchor" href="#미출시-—-2026-10-15-utc-08-00" aria-label="Permalink to &quot;미출시 — 2026-10-15 (UTC+08:00)&quot;">​</a></h2><ul><li>새 공개 문서와 Vue 3 기반 4개 언어 문서 사이트를 준비했습니다.</li><li>Windows x64/ARM64 다운로드와 Linux 스크립트/Docker 선택을 추가했습니다. 주소는 곧 제공됩니다.</li><li>비공개 파일 제외 규칙을 수정하고 내부 도구를 공개 소스 인덱스에서 제외했습니다.</li><li>공개 검증이 Equipment/Shop의 독립 테스트를 유지하고 로컬 데이터 사례만 제외하도록 수정했습니다.</li><li>기존 bootstrap 기본값을 보존하고 로컬 카탈로그 누락을 거짓 통과 대신 실패로 처리했습니다.</li></ul><p>첫 공개 릴리스를 위한 준비 기록이며 패키지나 사이트의 공개 완료를 뜻하지 않습니다. 상세 변경은 저장소 루트의 영어/중국어 변경 기록에서 관리합니다.</p>',7)])])}const _=l(o,[["render",r]]);export{p as __pageData,_ as default};
